// The sample project (samples/club-layout.lever, generated by
// scripts/make-sample-project.mjs) must stay valid and clean: no open track
// ends or unconnected junctions; only the deliberately missing addresses.
import {readFileSync} from 'node:fs';
import {join} from 'node:path';
import {describe, expect, it} from 'vitest';
import {loadProject} from '../../../model/migrations';
import {validateProject} from '../../../model/validation';

const SAMPLE = join(
  __dirname,
  '..',
  '..',
  '..',
  '..',
  'samples',
  'club-layout.lever',
);

describe('sample project', () => {
  const result = loadProject(readFileSync(SAMPLE, 'utf8'));

  it('loads', () => {
    expect(result.ok).toBe(true);
  });

  it('has only missing addresses as warnings', () => {
    if (!result.ok) {
      return;
    }
    const problems = validateProject(result.project);
    const unexpected = problems.filter(
      (problem) =>
        problem.severity !== 'info' && problem.code !== 'missingAddress',
    );
    expect(
      unexpected.map(
        (p) =>
          `${p.code} ${JSON.stringify(p.params)} ${p.elementIds.join(',')}`,
      ),
    ).toEqual([]);
  });
});
